#!/bin/sh
# تشغيل اختبارات المنطق النقي (upload وlogic وstorage وserver) بـNode ≥ 22 دون vitest. اختبارات server التي تحتاج PostgreSQL محلي تُتخطّى ما لم يُضبط ATHAR_TEST_PG (انظر scripts/local-pg.sh). architecture/repository/ui تحتاج Vite/vitest فعليًا ولا يغطيها هذا المشغّل.
cd "$(dirname "$0")/../.." || exit 1
exec node --experimental-strip-types --no-warnings --import ./scripts/node-test-runner/register.mjs --test src/test/upload.test.ts src/test/logic.test.ts src/test/storage.test.ts src/test/auth.test.ts src/test/supabaseData.test.ts src/test/teacherAuthClient.test.ts src/test/staffApiClient.test.ts server/test/objectKey.test.ts server/test/gate.test.ts server/test/psqlDb.test.ts server/test/uploadService.test.ts server/test/archive.test.ts server/test/teacherAuth.test.ts server/test/pgAuthStore.test.ts server/test/releaseOverview.test.ts server/test/api.test.ts server/test/archiveBuilder.test.ts server/test/sigv4r2.test.ts server/test/teacherRead.test.ts server/test/archiveService.test.ts server/test/compose.test.ts server/test/crc32.test.ts server/test/postgresDb.test.ts server/test/edgeHost.test.ts server/test/edgeBuild.test.ts server/test/auditSummary.test.ts server/test/depPaths.test.ts server/test/dependencyPolicy.test.ts server/test/auditTooling.test.ts
